  const toggleVisibleSelectable = (checked: boolean) => {
    setSelected((current) => {
      const next = new Set(current)
      selectableIds.forEach((id) => {
        if (checked) next.add(id)
        else next.delete(id)
      })
      return next
    })
  }

  const downloadExcel = () => {
    if (exportRows.length === 0) {
      setNotice('Выгружать нечего: по текущему набору нет заказов.')
      return
    }
