1959:                    {packingOrders.map((order) => {
2046:                <Alert severity="info">{workspace.supply.packaging_task_id ? 'Загружаем существующее задание упаковки…' : 'Сначала начните работу с поставкой — сервер создаст единственное задание упаковки.'}</Alert>
2048:              {nextStageControl('packing')}
2052:          {workspace && stage === 'boxes' ? (
