                          </Tooltip>
                        ) : null}
                      </TableCell>
                    </>
                </TableRow>
              )
              return (
                localSupplyMissing ? (
                  <Tooltip key={order.id} title={EXTERNAL_WB_SUPPLY_HINT} placement="top" arrow>
