    const asset: FbsPrintAsset = {
      id: `box-qr-${box.id}`,
      kind: 'box_qr',
      status: 'ready',
      content_type: 'image/png',
      width_mm: 58,
      height_mm: 40,
      preview_url: await renderBoxQrDataUrl(box.barcode),
      download_url: null,
