                    sx={{ width: 176 }}
                    data-task-id="CAL-02"
                  />
                  <Button
                    size="small"
                    variant="outlined"
                    onClick={() => void savePlannedShipmentDate()}
                    disabled={busy || plannedShipmentDateDraft === (workspace.supply.planned_shipment_date ?? '')}
                    data-testid="cal-02-fbs-shipment-date-save"
